package com.swir.stream;

import android.app.AlertDialog;
import android.content.Context;
import android.graphics.Bitmap;
import android.net.Uri;
import android.os.SystemClock;
import android.view.View;
import android.widget.*;
import androidx.test.core.app.ActivityScenario;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
import java.io.*;
import java.lang.reflect.*;
import java.net.InetAddress;
import java.nio.charset.StandardCharsets;
import java.security.KeyStore;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

@androidx.media3.common.util.UnstableApi @RunWith(AndroidJUnit4.class)
public final class PortalScannerUiTest {
    private Context context;private File folder;private String profile;private ProviderRepository repository;private final AtomicInteger probes=new AtomicInteger();
    private String sampleUrl="";
    private static final String TXT="https://portal.example.org/private/c/|02:00:00:00:00:01\nhttps://public.example.org/c/\nhttps://portal.example.org/private/c/|02:00:00:00:00:01\ninvalid\n";
    @Before public void setup()throws Exception{context=InstrumentationRegistry.getInstrumentation().getTargetContext();UiTestData.seed(context);profile=UUID.randomUUID().toString().replace("-","");folder=new File(context.getCacheDir(),"scanner-ui-"+profile);repository=new ProviderRepository(folder,profile,(u,h,c)->{String body=PortalScannerInstrumentedTest.body(u,h);if(u.contains("create_link")&&!sampleUrl.isEmpty())body="{\"js\":{\"cmd\":\""+sampleUrl+"\"}}";return new ProviderHttp.Document(u,body.getBytes(StandardCharsets.UTF_8),0,0);},host->new InetAddress[]{InetAddress.getByAddress(new byte[]{93,(byte)184,(byte)216,34})});}
    @After public void cleanup()throws Exception{UiTestData.restore(context);remove(folder);KeyStore keys=KeyStore.getInstance("AndroidKeyStore");keys.load(null);keys.deleteEntry("swir.providers.v1."+profile);}
    private static void remove(File f){if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File child:children)remove(child);}f.delete();}
    private static Object get(Object o,String name){try{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new AssertionError(e);}}
    private static void set(Object o,String name,Object value){try{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}catch(Exception e){throw new AssertionError(e);}}
    private static void call(MainActivity a,String name){try{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);}catch(Exception e){throw new AssertionError(e);}}
    private static void idle(){InstrumentationRegistry.getInstrumentation().waitForIdleSync();}
    private static PortalScannerDialog scanner(MainActivity a){return (PortalScannerDialog)get(a,"scannerPage");}
    private static AlertDialog page(MainActivity a){return (AlertDialog)get(scanner(a),"page");}
    private static View tagged(MainActivity a,String name){return page(a).getWindow().getDecorView().findViewWithTag(name);}
    private static void drain(ActivityScenario<MainActivity> scene,String name)throws Exception{CountDownLatch done=new CountDownLatch(1);scene.onActivity(a->((ExecutorService)get(a,name)).execute(done::countDown));assertTrue(done.await(20,TimeUnit.SECONDS));idle();}
    private ActivityScenario<MainActivity> launch()throws Exception{ActivityScenario<MainActivity> scene=ActivityScenario.launch(MainActivity.class);AtomicBoolean ready=new AtomicBoolean();long deadline=SystemClock.elapsedRealtime()+15000;while(!ready.get()&&SystemClock.elapsedRealtime()<deadline){scene.onActivity(a->ready.set(a.getWindow().getDecorView().findViewWithTag("channel_list")!=null));SystemClock.sleep(25);}assertTrue(ready.get());drain(scene,"work");drain(scene,"providerWork");scene.onActivity(a->{set(a,"providers",repository);set(a,"scannerEngine",new PortalScanner((entry,cancel,end)->{probes.incrementAndGet();return entry.account()?new PortalScanner.Result(PortalScanner.Status.CATALOG_AVAILABLE,1,false):PortalScanner.Result.status(PortalScanner.Status.CLIENT_FOUND);},1000,5000));try{Method method=MainActivity.class.getDeclaredMethod("providerSection",int.class);method.setAccessible(true);method.invoke(a,2);}catch(Exception e){throw new AssertionError(e);}});drain(scene,"providerWork");scene.onActivity(a->{AlertDialog manager=(AlertDialog)get(get(a,"providerPage"),"page");manager.getWindow().getDecorView().findViewWithTag("provider_scanner").performClick();});idle();return scene;}
    private void load(ActivityScenario<MainActivity> scene)throws Exception{scene.onActivity(a->scanner(a).beginImport(()->new ByteArrayInputStream(TXT.getBytes(StandardCharsets.UTF_8))));drain(scene,"scannerWork");}
    @Test public void visibleMacScannerPreviewMaskedResultsAndSelectedProtectedSave()throws Exception{try(ActivityScenario<MainActivity> scene=launch()){load(scene);scene.onActivity(a->{assertEquals(0,probes.get());String status=((TextView)tagged(a,"scanner_status")).getText().toString();assertTrue(status.contains("błędne wiersze: 1"));assertTrue(status.contains("duplikaty: 1"));Spinner list=(Spinner)tagged(a,"scanner_entries");assertEquals(2,list.getCount());assertFalse(list.getSelectedItem().toString().contains("02:00"));assertFalse(list.getSelectedItem().toString().contains("example.org"));tagged(a,"scanner_start").performClick();});drain(scene,"scannerWork");assertEquals(2,probes.get());assertTrue(repository.listSources().isEmpty());scene.onActivity(a->{assertTrue(((TextView)tagged(a,"scanner_result")).getText().toString().contains("odtwarzanie niesprawdzone"));});shot("scanner-results.png");scene.onActivity(a->tagged(a,"scanner_add").performClick());drain(scene,"scannerWork");drain(scene,"providerWork");assertEquals(1,repository.listSources().size());assertEquals(1,repository.stations().size());}}
    @Test public void cancelSuccessfulDelayedImportKeepsOldListAndReenablesActions()throws Exception{try(ActivityScenario<MainActivity> scene=launch()){load(scene);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);scene.onActivity(a->scanner(a).beginImport(()->new ByteArrayInputStream("https://other.example.org/c/".getBytes(StandardCharsets.UTF_8)){@Override public synchronized int read(byte[] buffer,int offset,int count){entered.countDown();try{release.await(5,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}return super.read(buffer,offset,count);}}));assertTrue(entered.await(5,TimeUnit.SECONDS));scene.onActivity(a->tagged(a,"scanner_cancel").performClick());release.countDown();drain(scene,"scannerWork");scene.onActivity(a->{assertEquals(2,((Spinner)tagged(a,"scanner_entries")).getCount());assertTrue(tagged(a,"scanner_import").isEnabled());assertTrue(tagged(a,"scanner_start").isEnabled());assertTrue(((TextView)tagged(a,"scanner_status")).getText().toString().contains("Anulowano import"));});}}
    @Test public void safResultIsBoundToOriginalDialogAndUrlOnlyFormHasBlankMac()throws Exception{try(ActivityScenario<MainActivity> scene=launch()){File file=new File(context.getCacheDir(),"scanner-saf-fixture.txt");try(FileOutputStream out=new FileOutputStream(file)){out.write("https://public.example.org/c/".getBytes(StandardCharsets.UTF_8));}scene.onActivity(a->{set(a,"pendingScannerImport",scanner(a));a.onActivityResult(73,android.app.Activity.RESULT_OK,new android.content.Intent().setData(Uri.fromFile(file)));});drain(scene,"scannerWork");scene.onActivity(a->tagged(a,"scanner_add").performClick());idle();scene.onActivity(a->{AlertDialog form=(AlertDialog)get(get(a,"providerPage"),"page");assertEquals("",((EditText)form.getWindow().getDecorView().findViewWithTag("provider_mac")).getText().toString());assertEquals("https://public.example.org/c/",((EditText)form.getWindow().getDecorView().findViewWithTag("provider_url")).getText().toString());});assertTrue(repository.listSources().isEmpty());file.delete();}}
    @Test public void publicSearchOpensPreparedPortalQueryAndFilter()throws Exception{try(ActivityScenario<MainActivity> scene=launch()){scene.onActivity(a->tagged(a,"scanner_web").performClick());idle();scene.onActivity(a->{Object explorer=get(a,"explorerPage");assertEquals("free public Stalker Ministra portal",get(explorer,"query"));assertEquals(3,get(explorer,"filter"));});assertEquals(0,probes.get());}}
    @Test public void closeAndRecreateDiscardTransientAccountsAndLateImport()throws Exception{try(ActivityScenario<MainActivity> scene=launch()){load(scene);AtomicReference<PortalScannerDialog> old=new AtomicReference<>();scene.onActivity(a->{old.set(scanner(a));set(a,"pendingScannerImport",old.get());});scene.recreate();idle();assertFalse(old.get().active());scene.onActivity(a->{assertNull(get(a,"scannerPage"));assertNull(get(a,"pendingScannerImport"));});assertTrue(repository.listSources().isEmpty());}}
    @Test public void profileChangeInvalidatesScannerAndPendingSafOwner()throws Exception{try(ActivityScenario<MainActivity> scene=launch()){load(scene);AtomicReference<PortalScannerDialog> old=new AtomicReference<>();scene.onActivity(a->{old.set(scanner(a));set(a,"pendingScannerImport",old.get());call(a,"profileChanged");assertNull(get(a,"pendingScannerImport"));});assertFalse(old.get().active());assertTrue(repository.listSources().isEmpty());}}
    @Test public void selectedScannerSampleActuallyDecodesPublicDashInEmbeddedPlayer()throws Exception{
        org.junit.Assume.assumeTrue("true".equals(InstrumentationRegistry.getArguments().getString("network")));sampleUrl="https://storage.googleapis.com/shaka-demo-assets/angel-one/dash.mpd";
        try(ActivityScenario<MainActivity> scene=launch()){File isolatedFolder=new File(folder,"isolated-ui-profile");assertTrue(isolatedFolder.mkdirs());scene.onActivity(a->{android.content.ContextWrapper isolated=new android.content.ContextWrapper(a){@Override public File getFilesDir(){return isolatedFolder;}};ProfileStore localProfiles=new ProfileStore(isolated);set(a,"profiles",localProfiles);set(a,"ai",new PersonalAi(isolated,localProfiles.currentId()));});load(scene);scene.onActivity(a->tagged(a,"scanner_start").performClick());drain(scene,"scannerWork");scene.onActivity(a->tagged(a,"scanner_play").performClick());drain(scene,"scannerWork");drain(scene,"providerWork");AtomicBoolean confirmed=new AtomicBoolean();AtomicLong watch=new AtomicLong();long deadline=SystemClock.elapsedRealtime()+35000;while(!confirmed.get()&&SystemClock.elapsedRealtime()<deadline){scene.onActivity(a->{SwirPlayer player=(SwirPlayer)get(a,"player");if(player!=null){assertFalse(player.isFailed());watch.set(player.watchedMillis());confirmed.set(player.isConfirmed()&&player.selectedAudio()&&player.selectedVideo()&&watch.get()>=1500);}});SystemClock.sleep(100);}assertTrue("Scanner selection must use the actual embedded AV renderer",confirmed.get());assertEquals(1,repository.listSources().size());File directory=new File(context.getExternalFilesDir(null),"evidence-v037");assertTrue(directory.isDirectory()||directory.mkdirs());try(FileOutputStream output=new FileOutputStream(new File(directory,"scanner-public-playback.json"))){output.write(new org.json.JSONObject().put("sdk",android.os.Build.VERSION.SDK_INT).put("fixturePortal","synthetic only; no operator contacted").put("publicMedia",sampleUrl).put("scannerSelectedSave",true).put("videoAndAudioConfirmed",true).put("movingTracksMs",watch.get()).toString(2).getBytes(StandardCharsets.UTF_8));}}
    }
    private void shot(String name)throws Exception{idle();InstrumentationRegistry.getInstrumentation().getUiAutomation().waitForIdle(300,4000);Bitmap bitmap=InstrumentationRegistry.getInstrumentation().getUiAutomation().takeScreenshot();assertNotNull(bitmap);File directory=new File(context.getExternalFilesDir(null),"evidence-v037");assertTrue(directory.isDirectory()||directory.mkdirs());try(FileOutputStream out=new FileOutputStream(new File(directory,name))){assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG,100,out));}bitmap.recycle();}
}
